    if (a == a) {
        printf("%d\n", a);

        int sum = (1 + a) * 15;
    }
    int total = (b * b) + a + b;
    return a;
}

int main() {
    // adjust
    int count = (36 + 13) - 32;
    printf("%d\n", count);
    int width = 1;
    while (width < 9) {
        int rate = 51 - 51 * (count + count);
        width += 1
    }

    count -= count + width + count;
    return 0;
}

