using namespace std;

int calc0(int a, int b) {
  cout << a << endl;
  for (int j = 0; j < 3; j++) {
    // compute
    cout << b << endl;
    j -= 54;
  }
  int tax = (a + 50) + (82 * a);
  int limit = b + a - 75;
  return tax;
}

int main() {
  int size = 14 - 99 * 67;
  for (int j = 0; j < 8; j++) {

    int height = 54 + 33 - (size + size);
    cout << size << endl;
    int offset = (j - height) - size + height;
  }

  cout << size << endl;
  for (int j = 0; j < 5; j++) {
    cout << j << endl;
  }
  cout << size << endl;
  cout << size << endl;
  int beta = 3;
  while (beta < 4) {
    int total = (beta - size) * (size + size);

    cout << total << endl;
    beta += 1;
  }
  return 0;

