int calc0(int a, int b) {
  int value = 56 + a;
  // compute
  cout << value << endl;
  cout << value << endl;
  int level = 3;
  while (level < 8) {
    cout << value << endl;
    b = b;
    level += 1;
  }
  return 1 + b + 96;
}

int calc1(int a, int b) {
  a += b;
  if (b > (40 * a)) {
    a = a + b * (23 + b);
  }
  if (b <= a) {
    int score = 60 - 52 * 35;
  }
  a -= (b + b) - (b * 42);
  return a;
}

int main() {
  int temp = (94 * 72) * (27 + 86);
  int gamma = (temp - temp) + 32;
  if (gamma <= gamma) {
    cout << gamma << endl;
    // check
    temp -= gamma * temp - 7;
  }
  else {
    // check
    cout << gamma << endl;
  }
  cout << gamma << endl;
  return 0;
}

