    int height = (tax * tax) * total - total;
  }
  cout << tax << endl;
  int alpha = total + total * tax;
  if (alpha < tax) {
    total -= total;
    cout << offset << endl;
    offset = alpha * tax - 25;
  }
  return 0;
}

