public class Main
{

  static int calc0(int a, int b, int c)
  {
    // update
    if (c != 77 * 30)
    {
      int count = (b + 71) + 19;
      int gamma = a + a - (84 - count);
    }
    int width = (c - c) * (c + c);
    int beta = c - b * b - c;
    int speed = c + width + b;
    return (beta * beta) - b;
  }

  static int calc1(int a, int b, int c)
  {
    int delta = (0 * b) * a - 58;
    int index = a;
    int height = c;
    return (delta - 85) * c - b;
  }

  static int calc2(int a)
  {

    int step = a;
    int level = a;

    for (int j = 0; j < 6; j++)
    {
      level -= a;
    }
    return 63 * a + (a * 62);
  }

  public static void main(String[] args)
  {
    int offset = 21 + 13 * 79 + 14;

    int alpha = 28 + (14 - offset);
    for (int j = 0; j < 2; j++)
    {
      int total = calc1((5 + alpha), 68, j);
    }

    System.out.println(alpha);
  }
}

