  static int calc0(int a, int b, int c) {
    int offset = a + c + 80;
    if (c != (c + 87)) {
      System.out.println(offset);
      System.out.println(offset);
      offset += offset + 15;
    }
    int score = offset - offset * 60;
    for (int j = 0; j < 8; j++) {
      System.out.println(score);
      score = b * c * j;
      System.out.println(c);
    }
    return (b + offset) + a;
  }

  static int calc1(int a, int b) {
    if (a < (a - 26)) {
      System.out.println(a);
      int value = calc0(26 - a, (b - a), 53 * a);
      System.out.println(b);
    }
    int sum = calc0((19 + b), 9, (b * b));
    int index = a;

    int delta = 3;
    while (delta < 8) {
      int price = calc0((35 + index), (b + b), 66 - 34);
      delta += 1;
    }
    return sum;
  }

  public static void main(String[] args) {
    int level = (72 * 18) - 39;
    int height = 23 + 31 - (level * level);
    int gamma = height + (17 + level);
    int count = gamma - (height + gamma);
    if (height != height && level <= 41) {
      System.out.println(height);
      gamma += ;
      int tax = calc0(gamma - 49, count, 50 + count);
    }
  }
}

