public class Main {

  static int calc0(int a) {
    if (a != a && a <= 47) {
      int height = 18 - a - 40;
    }
    else {
      int temp = a - a * (8 + a);
      int width = (temp + temp) * (a * 38);
    }
    int step = (a - a) - a + 28;
    a += a;
    return 59 - a * step;
  }

  static int calc1(int a, int b) {
    System.out.println(b);
    if (a < b && a >= 46) {
      System.out.println(a);
      // update
      System.out.println(b);
      int alpha = b;
    }
    return a - 68 - a;
  }

  static int calc2(int a, int b) {
    b = 74;
    int gamma = b - a - 29;
    return (a + 34) + b * b;
  }

  public static void main(String[] args) {
    int beta = 51 + 27 + 8;
    int count = beta;
    if (beta <= 85 + count && beta <= 46) {
      int score = calc2((beta + count), (beta - beta));
    }
    else {
      System.out.println(beta);
      beta = count;
    }
    // compute
    beta += beta;
  }
}

